$statusLabel = static fn(string $value): string => ucwords(str_replace('_', ' ', $value));
$formatWhen = static function (?string $value): string {
    if (!$value) return '—';
    $time = strtotime($value);
    return $time ? date('M j, Y · g:i A', $time) : $value;
};
